"""An application generated by stackr's 0.1.0 template, updated with `copier update` to this one.

It is generated at the `stackr-v0.1.0` tag with the defaults, committed as its owner would, and
updated to this commit's template with the defaults for the questions 0.1.0 didn't ask. The update
must apply cleanly, with no conflict and no rejected hunk, and leave exactly what a new
application generated from this commit would be: the template's changes since 0.1.0, every one.

Copier's own generation only: it doesn't lock, build or run the application, which needs the
libraries from GitHub at a pushed commit and Docker (`scripts/smoke app` and the template's CI
jobs run those on a fresh application).
"""

import re
import shutil
import subprocess
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
RELEASED = "stackr-v0.1.0"
PINNED = re.compile(r'rev = "[0-9a-f]{40}"')
"""The libraries' pins at the template's commit, which a working tree with changes in it makes
a commit of its own for each run of copier."""


def _copier(*arguments: str, cwd: Path) -> None:
    subprocess.run(["uv", "run", "copier", *arguments], cwd=cwd, check=True, capture_output=True)


def _git(*arguments: str, cwd: Path) -> None:
    subprocess.run(
        ["git", "-c", "user.name=t", "-c", "user.email=t@example.com", *arguments],
        cwd=cwd,
        check=True,
        capture_output=True,
    )


def _released() -> bool:
    done = subprocess.run(
        ["git", "rev-parse", "--verify", "--quiet", f"{RELEASED}^{{commit}}"],
        cwd=ROOT,
        capture_output=True,
        check=False,
    )
    return done.returncode == 0


def _files(directory: Path) -> dict[str, str]:
    """Each file the application has, but git's and copier's answers, with the pins made one."""
    return {
        str(path.relative_to(directory)): PINNED.sub('rev = "<pin>"', path.read_text())
        for path in sorted(directory.rglob("*"))
        if path.is_file() and ".git" not in path.parts and path.name != ".copier-answers.yml"
    }


@pytest.mark.timeout(300)
@pytest.mark.skipif(shutil.which("git") is None, reason="needs git")
def test_an_application_from_0_1_0_updates_to_this_template(tmp_path: Path) -> None:
    if not _released():
        pytest.skip(f"{RELEASED} isn't in this clone: fetch the tags")
    application, fresh = tmp_path / "application", tmp_path / "fresh"
    answers = ["--quiet", "--defaults", "--data", "project_name=Upgraded"]
    _copier("copy", *answers, "--vcs-ref", RELEASED, str(ROOT), str(application), cwd=tmp_path)
    _git("init", "--quiet", cwd=application)
    _git("add", "--all", cwd=application)
    _git("commit", "--quiet", "--message", "generated by stackr 0.1.0", cwd=application)

    _copier("update", "--quiet", "--defaults", "--vcs-ref", "HEAD", str(application), cwd=ROOT)

    leftovers = [
        str(path.relative_to(application))
        for path in application.rglob("*")
        if path.is_file()
        and ".git" not in path.parts
        and (path.suffix == ".rej" or "<<<<<<< " in path.read_text(errors="replace"))
    ]
    assert leftovers == [], "the update left conflicts"
    _copier("copy", *answers, "--vcs-ref", "HEAD", str(ROOT), str(fresh), cwd=tmp_path)
    updated, generated = _files(application), _files(fresh)
    assert sorted(updated) == sorted(generated), "the update made other files than a new one has"
    differ = [name for name in generated if updated[name] != generated[name]]
    assert differ == [], "the update left files other than a new application has them"
